const docWindow=root=>root.ownerDocument.defaultView||window;
import{escapeStaff as esc,staffIcon as icon,roleLabel}from './staff-markup.js';
const initials=name=>[...String(name||'С').trim()].slice(0,2).join('').toUpperCase();
export function staffMessengerMarkup(){return '<div class="staff-chat staff-messenger" data-messenger-view="list"><aside class="staff-chat-side"><header class="staff-inbox-heading"><h2>Сообщения</h2><span class="staff-inbox-count" data-inbox-count></span></header><label class="staff-chat-search">'+icon('messages')+'<input type="search" maxlength="80" aria-label="Найти переписку" placeholder="Найти переписку"></label><nav class="staff-inbox-filters" aria-label="Переписки"><button type="button" data-inbox-filter="all" aria-pressed="true">Все</button><button type="button" data-inbox-filter="direct" aria-pressed="false">Личные</button><button type="button" data-inbox-filter="team" aria-pressed="false">Общий чат</button></nav><h3 class="staff-inbox-label">Переписки</h3><div data-rooms></div><h3 class="staff-inbox-label">Написать сотруднику</h3><div data-contacts></div></aside><section class="staff-conversation"><header class="staff-chat-heading"><button type="button" class="staff-icon-button" data-messenger-back aria-label="К перепискам">'+icon('back')+'</button><span class="staff-conversation-avatar" aria-hidden="true" data-conversation-avatar>С</span><div><strong data-chat-title>Команда SALAH</strong><small data-chat-subtitle>Общий чат команды</small></div></header><div data-staff-push-control></div><div class="staff-chat-messages" role="log" aria-label="Переписка" aria-live="polite" aria-relevant="additions text"></div><form class="staff-composer"><div class="staff-pending-files"></div><div class="staff-emoji" hidden>'+['🙂','😊','🤍','👍','🤲','🙏','✨','🌙','✅','👏','💬','📌'].map(x=>'<button type="button" data-emoji="'+x+'" aria-label="'+x+'">'+x+'</button>').join('')+'</div><div class="staff-composer-row"><button class="staff-icon-button" type="button" data-smile aria-label="Смайлики" aria-expanded="false">'+icon('smile')+'</button><button class="staff-icon-button" type="button" data-attach aria-label="Прикрепить файл">'+icon('file')+'</button><textarea maxlength="5000" aria-label="Сообщение" placeholder="Напишите сообщение…"></textarea><button class="staff-icon-button staff-send" type="submit" aria-label="Отправить">'+icon('send')+'</button><input type="file" hidden multiple data-chat-file accept=".pdf,.txt,.jpg,.jpeg,.png,.zip,.docx,.xlsx,.pptx"></div></form></section></div>';}
export function mountStaffMessenger(root,{rooms,contacts,onRoom,onContact,onRendered=()=>{},initialRoom=null}={}){
 const win=docWindow(root);let selected=null,filter='all',query='',disposed=false;const doc=root.ownerDocument,list=root.querySelector('[data-rooms]'),people=root.querySelector('[data-contacts]'),search=root.querySelector('input[type=search]');
 function viewport(){const height=Math.max(300,Math.min(680,(win.visualViewport?.height||win.innerHeight||800)*.72));root.style.setProperty('--staff-conversation-height',Math.round(height)+'px');}
 const typing=()=>{if(disposed)return;const focused=root.querySelector('textarea')===doc.activeElement;doc.body.classList.toggle('staff-messenger-typing',focused&&root.getBoundingClientRect().width<600);viewport();};
 const onFocus=()=>{typing();if(root.getBoundingClientRect().width<600)root.querySelector('.staff-conversation')?.scrollIntoView?.({block:'start',behavior:'instant'});};root.querySelector('textarea').addEventListener('focus',onFocus);const onBlur=()=>queueMicrotask(typing);root.querySelector('textarea').addEventListener('blur',onBlur);win.visualViewport?.addEventListener('resize',viewport);viewport();
 function roomTitle(room){return room.title||'Переписка';}
 function renderRooms(rows=rooms,current=selected){if(disposed)return;rooms=rows;selected=current;const count=rooms.reduce((sum,r)=>sum+(Number.isSafeInteger(r.unread)&&r.unread>0?r.unread:0),0);root.querySelector('[data-inbox-count]').textContent=count?'Новых: '+(count>99?'99+':String(count)):'';const visible=rooms.filter(r=>(filter==='all'||(filter==='team')===(r.kind==='team'))&&roomTitle(r).toLowerCase().includes(query));
  list.innerHTML=visible.length?visible.map(r=>'<button type="button" class="staff-chat-room" data-room="'+esc(r.id)+'" aria-current="'+(r.id===selected?.id)+'"><span class="staff-room-avatar'+(r.peerId?' staff-avatar':'')+'"'+(r.peerId?' data-member-avatar="'+esc(r.peerId)+'"':'')+' aria-hidden="true">'+(r.kind==='team'?icon('team'):esc(initials(roomTitle(r))))+'</span><span class="staff-room-copy"><strong>'+esc(roomTitle(r))+'</strong><small>'+esc(r.last_message||'Начните разговор')+'</small></span>'+(r.unread?'<span class="staff-room-unread" aria-label="Непрочитанных: '+esc(r.unread)+'">'+esc(r.unread>99?'99+':r.unread)+'</span>':'')+'</button>').join(''):'<p class="staff-empty">'+(query?'Переписки не найдены.':'Здесь пока нет переписок.')+'</p>';
  people.hidden=filter==='team';people.previousElementSibling.hidden=filter==='team';people.innerHTML=contacts.filter(p=>p.nickname.toLowerCase().includes(query)).map(p=>'<button type="button" class="staff-chat-room staff-chat-contact" data-contact="'+esc(p.id)+'"><span class="staff-avatar staff-room-avatar" data-member-avatar="'+esc(p.id)+'" aria-hidden="true">'+esc(initials(p.nickname))+'</span><span class="staff-room-copy"><strong>'+esc(p.nickname)+'</strong><small>'+esc(roleLabel(p.role))+'</small></span></button>').join('');onRendered();
 }
 function showConversation(room){if(disposed)return;selected=room;root.dataset.messengerView='chat';root.querySelector('[data-chat-title]').textContent=roomTitle(room);root.querySelector('[data-chat-subtitle]').textContent=room.kind==='team'?'Общий чат команды':'Личная переписка';const avatar=root.querySelector('[data-conversation-avatar]');if(room.peerId){avatar.dataset.memberAvatar=room.peerId;avatar.classList.add('staff-avatar');}else{delete avatar.dataset.memberAvatar;avatar.classList.remove('staff-avatar');}avatar.innerHTML=room.kind==='team'?icon('team'):esc(initials(roomTitle(room)));renderRooms(rooms,selected);}
 root.querySelector('[data-messenger-back]').onclick=()=>{root.dataset.messengerView='list';const heading=root.querySelector('.staff-inbox-heading h2');heading.tabIndex=-1;heading.focus({preventScroll:true});root.scrollIntoView?.({block:'start',behavior:'instant'});};
 root.querySelector('[data-rooms]').onclick=e=>{const b=e.target.closest('[data-room]');if(b)onRoom(rooms.find(r=>r.id===b.dataset.room));};people.onclick=e=>{const b=e.target.closest('[data-contact]');if(b)onContact(b.dataset.contact);};
 search.oninput=()=>{query=search.value.trim().toLowerCase();renderRooms();};for(const button of root.querySelectorAll('[data-inbox-filter]'))button.onclick=()=>{filter=button.dataset.inboxFilter;for(const b of root.querySelectorAll('[data-inbox-filter]'))b.setAttribute('aria-pressed',String(b===button));renderRooms();};
 renderRooms();if(initialRoom){const row=rooms.find(r=>r.id===initialRoom);if(row)showConversation(row);}
 return{renderRooms,showConversation,isConversationVisible:()=>root.dataset.messengerView==='chat'||root.getBoundingClientRect().width>=600,dispose(){disposed=true;doc.body.classList.remove('staff-messenger-typing');root.querySelector('textarea')?.removeEventListener('focus',onFocus);root.querySelector('textarea')?.removeEventListener('blur',onBlur);win.visualViewport?.removeEventListener('resize',viewport);}};
}
